93	    /**
94	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
95	     * new owner's id, customer code, registration date, membership level and membership number.
96	     */
97	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
98	
99	    /**
100	     * Common street-type abbreviations expanded during address normalization. Keys are the
101	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
102	     * expanded form it is replaced with.
103	     */
104	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
105	        "ST", "STREET",
106	        "RD", "ROAD",
107	        "AVE", "AVENUE");
108	
109	    /**
110	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
111	     * is at capacity and cannot take any more.
112	     */
113	    private static final int CITY_CAPACITY = 50;
114	
115	    /**
116	     * The maximum number of owners that may be registered in a single day. Once this many owners
117	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
118	     * owners can be created that day.
119	     */
120	    private static final int DAILY_OWNER_LIMIT = 100;
121	
122	    /**
123	     * The number of owners that may be registered on a single business day before a response starts
124	     * carrying a {@code bulkSignupWarning}. Once <em>more than</em> this many owners already carry the
125	     * current business day's {@code registrationDate}, that day's signups are flagged as unusually
126	     * high volume.
127	     */
128	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
129	
130	    /**
131	     * Fixed public holidays that the business-day roll skips over. A registration date that lands on
132	     * one of these dates is rolled forward to the next non-holiday business day, exactly as a weekend
133	     * date is rolled forward off a Saturday or Sunday.
134	     */
135	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
136	        LocalDate.parse("2026-01-01"),
137	        LocalDate.parse("2026-01-26"),
138	        LocalDate.parse("2026-04-25"),
139	        LocalDate.parse("2026-12-25"),
140	        LocalDate.parse("2026-12-28"));
141	
142	    /**
143	     * E.164 country codes mapped to the exact number of national (significant) digits a telephone for
144	     * that country must carry. For example {@code '+61'} (Australia) requires 9 national digits and
145	     * {@code '+1'} (NANP) requires 10. A country code listed here enforces that national-number length;
146	     * a number whose country code is not listed is accepted at any otherwise-valid E.164 length.
147	     */
148	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
149	        "61", 9,
150	        "1", 10);
151	
152	    /**
153	     * Fixed region-to-postcode-range lookup used both to validate an owner's optional postcode against
154	     * the region derived from the owner's city ({@link #regionForCity}) and to derive the postcode's own
155	     * region for the {@code customerCode} ({@link #regionForPostcode}). Each value is the inclusive
156	     * {@code {low, high}} 4-digit range for that region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A
157	     * region that is not listed ({@code 'UNKNOWN'}) carries no range and accepts any 4-digit postcode.
158	     */
159	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
160	        "NSW", new int[] {2000, 2099},
161	        "VIC", new int[] {3000, 3099},
162	        "QLD", new int[] {4000, 4099});
163	
164	    /**
165	     * Fixed city-to-region lookup used to validate an owner's optional postcode against the region
166	     * derived from the owner's city. Any city not listed has region {@code 'UNKNOWN'} and so accepts
167	     * any 4-digit postcode.
168	     */
169	    private static final Map<String, String> CITY_REGION = Map.of(
170	        "Sydney", "NSW",
171	        "Melbourne", "VIC",
172	        "Brisbane", "QLD");
