174	    /**
175	     * Remembers the owner created for each {@code Idempotency-Key} seen on a create request, keyed by
176	     * the header value. A repeated create carrying a key already present here is served the originally
177	     * created owner instead of creating a duplicate, so retries are safe. The map only ever grows with
178	     * distinct keys and is held for the application's lifetime, consistent with the in-memory, single
179	     * instance scope of this sample.
180	     */
181	    private final Map<String, Integer> idempotentCreateOwnerIds = new ConcurrentHashMap<>();
