228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
231	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
232	        if (replay != null) {
233	            return replay;
234	        }
235	        validateRequiredFields(ownerFieldsDto);
236	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
237	        LocalDate registrationDate = toBusinessDay(
238	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
239	        rejectDailyLimitReached(registrationDate);
240	        HttpHeaders headers = new HttpHeaders();
241	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
242	        applyAddress(owner, ownerFieldsDto);
243	        rejectCityAtCapacity(owner.getCity());
244	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
245	        owner.setTelephone(telephone);
246	        String email = normalizeEmail(ownerFieldsDto.getEmail());
247	        owner.setEmail(email);
248	        owner.setPostcode(validatePostcode(ownerFieldsDto.getPostcode(), regionForCity(owner.getCity())));
249	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
250	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
251	        rejectDuplicateIdentity(owner);
252	        applyPossibleDuplicate(owner, sharesHousehold);
253	        owner.setRegistrationDate(registrationDate);
254	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
255	        owner.setCustomerCode(generateCustomerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName()));
256	        owner.setMembershipLevel(cappedMembershipLevel(owner));
257	        this.clinicService.saveOwner(owner);
258	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
259	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
260	            owner.getMembershipLevel(), owner.getMembershipNumber());
261	        rememberIdempotentCreate(idempotencyKey, owner.getId());
262	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
263	        applyBulkSignupWarning(ownerDto);
264	        headers.setLocation(UriComponentsBuilder.newInstance()
265	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
266	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
267	    }
268	
269	    /**
270	     * Serves a repeated create that carries an {@code Idempotency-Key} already seen on an earlier
271	     * successful create. When the key has a remembered owner that still exists, the originally created
272	     * owner is returned with {@code 200 OK} (carrying its {@code Location}) so the retry neither creates
273	     * a duplicate nor re-runs the create rules. A {@code null} or blank key, an unseen key, or a key
274	     * whose owner no longer exists yields {@code null}, signalling the caller to perform a normal create.
275	     *
276	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
277	     * @return the originally created owner as a {@code 200 OK} response, or {@code null} to create normally
278	     */
279	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
280	        if (isBlank(idempotencyKey)) {
281	            return null;
282	        }
283	        Integer ownerId = idempotentCreateOwnerIds.get(idempotencyKey);
284	        if (ownerId == null) {
285	            return null;
286	        }
287	        Owner owner = this.clinicService.findOwnerById(ownerId);
288	        if (owner == null) {
289	            return null;
290	        }
291	        HttpHeaders headers = new HttpHeaders();
292	        headers.setLocation(UriComponentsBuilder.newInstance()
293	            .path(OwnerMapper.OWNER_PATH_TEMPLATE).buildAndExpand(owner.getId()).toUri());
294	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
295	        applyBulkSignupWarning(ownerDto);
296	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.OK);
297	    }
298	
299	    /**
300	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
301	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
302	     * blank key is ignored, leaving that create non-idempotent.
303	     *
304	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
305	     * @param ownerId        the id of the owner that was just created
306	     */
307	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
308	        if (!isBlank(idempotencyKey)) {
309	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
310	        }
311	    }
