408	    /**
409	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
410	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
411	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
412	     *
413	     * @param ownerFieldsDto the submitted owner fields
414	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
415	     *                                     name of every offending field
416	     */
417	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
418	        List<String> missingFields = new ArrayList<>();
419	        if (isBlank(ownerFieldsDto.getFirstName())) {
420	            missingFields.add("firstName");
421	        }
422	        if (isBlank(ownerFieldsDto.getLastName())) {
423	            missingFields.add("lastName");
424	        }
425	        if (!hasAddress(ownerFieldsDto)) {
426	            missingFields.add("address");
427	        }
428	        if (isBlank(ownerFieldsDto.getCity())) {
429	            missingFields.add("city");
430	        }
431	        if (isBlank(ownerFieldsDto.getTelephone())) {
432	            missingFields.add("telephone");
433	        }
434	        if (!missingFields.isEmpty()) {
435	            throw new InvalidOwnerFieldsException(missingFields);
436	        }
437	    }
438	
439	    private boolean isBlank(String value) {
440	        return value == null || value.isBlank();
441	    }
442	
443	    /**
444	     * Reports whether an existing owner has not been soft-deleted. The create endpoint's duplicate
445	     * and identity checks consider only live owners, so an owner flagged {@code deleted} no longer
446	     * blocks a new owner that would otherwise match it.
447	     *
448	     * @param owner an existing owner
449	     * @return {@code true} unless the owner is flagged deleted
450	     */
451	    private boolean isNotDeleted(Owner owner) {
452	        return !Boolean.TRUE.equals(owner.getDeleted());
453	    }
454	
455	    /**
456	     * Rejects a supplied {@code registrationDate} that is later than the current server date. A
457	     * {@code null} value means the field was omitted and the registration date will default to the
458	     * server date, so there is nothing to reject. A supplied date on or before today is accepted; the
459	     * raw supplied value is compared against the server date before any business-day adjustment.
460	     *
461	     * @param registrationDate the registration date supplied by the client, or {@code null} if omitted
462	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server date, yielding a
463	     *                                     400 Bad Request response
464	     */
465	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
466	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
467	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
468	        }
469	    }
470	
471	    /**
472	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
473	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
474	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
475	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
476	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
477	     * The returned value is stored and returned unchanged.
478	     *
479	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
480	     * @param region   the owner's region derived from its city
481	     * @return the postcode to store, or {@code null} if none was supplied
482	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
483	     *                                     out of range for the city's region, yielding a 400 response
484	     */
485	    private String validatePostcode(String postcode, String region) {
486	        if (postcode == null) {
487	            return null;
488	        }
489	        if (!postcode.matches("[0-9]{4}")) {
490	            throw new InvalidOwnerFieldsException(List.of("postcode"));
491	        }
492	        int[] range = REGION_POSTCODES.get(region);
493	        if (range != null) {
494	            int value = Integer.parseInt(postcode);
495	            if (value < range[0] || value > range[1]) {
496	                throw new InvalidOwnerFieldsException(List.of("postcode"));
497	            }
498	        }
499	        return postcode;
500	    }
501	
502	    /**
503	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
504	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
505	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
506	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
507	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
508	     *
509	     * @param telephone the raw telephone value submitted by the client
510	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
511	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
512	     *                                     400 response
513	     */
514	    private String normalizeTelephone(String telephone) {
515	        String e164 = toE164(telephone);
516	        if (e164 == null) {
517	            throw new InvalidOwnerFieldsException(List.of("telephone"));
518	        }
519	        return e164;
520	    }
521	
522	    /**
523	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
524	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
525	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
526	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
527	     * and when the supplied country code is one with a known national-number length
528	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
529	     * number must have exactly that many digits.
530	     *
531	     * @param telephone the raw telephone value, possibly {@code null}
532	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
533	     */
534	    private String toE164(String telephone) {
535	        if (telephone == null) {
536	            return null;
537	        }
538	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
539	        boolean hasPlus = cleaned.startsWith("+");
540	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
541	        String nationalSignificant = hasPlus
542	            ? digits
543	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
544	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
545	            return null;
546	        }
547	        if (!hasValidNationalNumberLength(nationalSignificant)) {
548	            return null;
549	        }
550	        return "+" + nationalSignificant;
551	    }
552	
553	    /**
554	     * Checks the national-number length of an E.164 number (country code plus national significant
555	     * digits, no leading {@code '+'}) against the per-country requirement in
556	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
557	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
558	     * country code is not listed carries no per-country length requirement and is accepted.
559	     *
560	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
561	     *                            leading {@code '+'}
562	     * @return {@code true} if the national-number length is correct for the country code, or the
563	     *         country code has no listed requirement; {@code false} otherwise
564	     */
565	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
566	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
567	            .filter(nationalSignificant::startsWith)
568	            .max(Comparator.comparingInt(String::length))
569	            .orElse(null);
570	        if (countryCode == null) {
571	            return true;
572	        }
573	        int nationalLength = nationalSignificant.length() - countryCode.length();
574	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
575	    }
576	
577	    /**
578	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
579	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
580	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
581	     * returned value is that address lower-cased.
582	     *
583	     * @param email the raw email value submitted by the client, or {@code null} if omitted
584	     * @return the lower-cased email, or {@code null} if none was supplied
585	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
586	     *                                     or its domain is a disposable-mail domain, yielding a 400
587	     *                                     response
588	     */
589	    private String normalizeEmail(String email) {
590	        if (email == null) {
591	            return null;
592	        }
593	        if (!EMAIL_PATTERN.matcher(email).matches()) {
594	            throw new InvalidOwnerFieldsException(List.of("email"));
595	        }
596	        String normalized = email.toLowerCase(Locale.ROOT);
597	        String domain = normalized.substring(normalized.indexOf('@') + 1);
598	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
599	            throw new InvalidOwnerFieldsException(List.of("email"));
600	        }
601	        return normalized;
602	    }
603	
604	    /**
605	     * Counts the existing owners that, before this create, already share the given first name and
606	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
607	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
608	     * been saved yet, so it is never included in the count.
609	     *
610	     * @param firstName the first name of the owner being created
611	     * @param lastName  the last name of the owner being created
612	     * @return the number of existing owners sharing both names
613	     */
614	    private int countNamesakes(String firstName, String lastName) {
615	        String normalizedFirstName = normalizeForComparison(firstName);
616	        String normalizedLastName = normalizeForComparison(lastName);
617	        return (int) this.clinicService.findAllOwners().stream()
618	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
619	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
620	            .count();
621	    }
622	
623	    /**
624	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
625	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
626	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
627	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
628	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
629	     * same postcode region, telephone and last name always yield the same customer code.
630	     *
631	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
632	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
633	     * it unique, so distinct owners always receive distinct customer codes.
634	     *
635	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
636	     * @param telephone the owner's normalized (E.164) telephone
637	     * @param lastName  the owner's last name
638	     * @return the formatted, de-duplicated customer code
639	     */
640	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
641	        String region = regionForPostcode(postcode);
642	        String hash8 = hashHex(telephone + lastName, 8);
643	        String baseCode = region + "-" + hash8;
644	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
645	            .map(Owner::getCustomerCode)
646	            .filter(Objects::nonNull)
647	            .collect(Collectors.toSet());
648	        if (!existingCodes.contains(baseCode)) {
649	            return baseCode;
650	        }
651	        int n = 2;
652	        while (existingCodes.contains(baseCode + "-" + n)) {
653	            n++;
654	        }
655	        return baseCode + "-" + n;
656	    }
657	
658	    /**
659	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
660	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
661	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
662	     * {@code <REGION>} segment baked into the {@code customerCode}.
663	     *
664	     * @param postcode the owner's postcode, or {@code null}
665	     * @return the region code, or {@code 'UNKNOWN'}
666	     */
667	    private String regionForPostcode(String postcode) {
668	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
669	            return "UNKNOWN";
670	        }
671	        int value = Integer.parseInt(postcode);
672	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
673	            int[] range = entry.getValue();
674	            if (value >= range[0] && value <= range[1]) {
675	                return entry.getKey();
676	            }
677	        }
678	        return "UNKNOWN";
679	    }
680	
681	    /**
682	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
683	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
684	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
685	     * region.
686	     *
687	     * @param city the owner's city
688	     * @return the region code, or {@code 'UNKNOWN'}
689	     */
690	    private String regionForCity(String city) {
691	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
692	    }
693	
694	    /**
695	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
696	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
697	     * deterministic {@code householdId} (length 12).
698	     *
699	     * @param input  the value to hash
700	     * @param length the number of leading hex characters to return
701	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
702	     */
703	    private String hashHex(String input, int length) {
704	        try {
705	            byte[] digest = MessageDigest.getInstance("SHA-256")
706	                .digest(input.getBytes(StandardCharsets.UTF_8));
707	            StringBuilder hex = new StringBuilder(digest.length * 2);
708	            for (byte b : digest) {
709	                hex.append(String.format("%02x", b));
710	            }
711	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
712	        } catch (NoSuchAlgorithmException e) {
713	            throw new IllegalStateException("SHA-256 algorithm not available", e);
714	        }
715	    }
716	
717	    /**
718	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
719	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
720	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
721	     * has not been saved yet, so it is never included in the count.
722	     *
723	     * @param city the city of the owner being created
724	     * @return the number of existing owners in that city
725	     */
726	    private int countOwnersInCity(String city) {
727	        String normalizedCity = normalizeForComparison(city);
728	        return (int) this.clinicService.findAllOwners().stream()
729	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
730	            .count();
731	    }
732	
733	    /**
734	     * Rejects creation of an owner whose city already contains the maximum number of owners
735	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
736	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
737	     *
738	     * @param city the city of the owner being created
739	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
740	     *                                      owners, yielding a 409 Conflict response
741	     */
742	    private void rejectCityAtCapacity(String city) {
743	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
744	            throw new OwnerCityAtCapacityException(city);
745	        }
746	    }
747	
748	    /**
749	     * Rejects creation of an owner once the given business day has already reached its daily quota
750	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
751	     * being that day — the adjusted business day the owner being created will carry — so the quota
752	     * applies per business day. The owner being created has not been saved yet, so it is never
753	     * included in the count.
754	     *
755	     * @param registrationDate the adjusted business-day registration date of the owner being created
756	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
757	     *                                         carry that registration date, yielding a
758	     *                                         429 Too Many Requests response
759	     */
760	    private void rejectDailyLimitReached(LocalDate registrationDate) {
761	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
762	            throw new DailyOwnerLimitReachedException(registrationDate);
763	        }
764	    }
765	
766	    /**
767	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
768	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
769	     *
770	     * @param registrationDate the business day to count owners for
771	     * @return the number of existing owners registered on that day
772	     */
773	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
774	        return this.clinicService.findAllOwners().stream()
775	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
776	            .count();
777	    }
778	
779	    /**
780	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
781	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
782	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
783	     * otherwise.
784	     *
785	     * @param ownerDto the owner response to flag
786	     */
787	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
788	        LocalDate today = toBusinessDay(LocalDate.now());
789	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
790	    }
791	
792	    /**
793	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
794	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
795	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
796	     * returned unchanged. This applies to the effective registration date whether it was supplied in
797	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
798	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
799	     * year segment and the daily create-limit's per-day bucket).
800	     *
801	     * @param date the effective registration date, supplied or defaulted
802	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
803	     */
804	    private LocalDate toBusinessDay(LocalDate date) {
805	        LocalDate adjusted = date;
806	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
807	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
808	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
809	            adjusted = adjusted.plusDays(1);
810	        }
811	        return adjusted;
812	    }
813	
814	    /**
815	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
816	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
817	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
818	     * separate telephone, email and household checks are all expressed through it. Because the
819	     * telephone is part of the key, two members of the same household (same {@code householdId})
820	     * with different telephones have different identity keys and are both allowed; only a whole-key
821	     * match is a duplicate. The owner being created already carries its normalized telephone,
822	     * email and (if any) household id, and existing owners store the same normalized forms, so the
823	     * keys are compared directly.
824	     *
825	     * @param owner the owner being created, with its telephone, email and household id already set
826	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
827	     *                                         yielding a 409 Conflict response
828	     */
829	    private void rejectDuplicateIdentity(Owner owner) {
830	        String identityKey = owner.getIdentityKey();
831	        boolean inUse = this.clinicService.findAllOwners().stream()
832	            .filter(this::isNotDeleted)
833	            .map(Owner::getIdentityKey)
834	            .anyMatch(identityKey::equals);
835	        if (inUse) {
836	            throw new DuplicateOwnerIdentityException(identityKey);
837	        }
838	    }
839	
840	    /**
841	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
842	     * that is not a hard duplicate (its identity key is unique, so it has already passed
843	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
844	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
845	     * while carrying a different telephone. When such a match exists the owner is created with
846	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
847	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
848	     * {@code false} and {@code possibleDuplicateOf} is left unset.
849	     *
850	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
851	     * declared household member is not a suspected duplicate. Without that declaration a same-household
852	     * owner with a different telephone is still created, carrying the {@code possibleDuplicate} flag so
853	     * it can be reviewed.
854	     *
855	     * @param owner           the owner being created, with its household id and telephone already set
856	     * @param sharesHousehold whether the owner declared itself a member of an existing household
857	     */
858	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
859	        owner.setPossibleDuplicate(false);
860	        if (sharesHousehold) {
861	            return;
862	        }
863	        String householdId = owner.getHouseholdId();
864	        if (householdId == null || householdId.isBlank()) {
865	            return;
866	        }
867	        String telephone = owner.getTelephone();
868	        Owner match = this.clinicService.findAllOwners().stream()
869	            .filter(this::isNotDeleted)
870	            .filter(existing -> householdId.equals(existing.getHouseholdId())
871	                && !Objects.equals(telephone, existing.getTelephone()))
872	            .min(Comparator.comparingInt(Owner::getId))
873	            .orElse(null);
874	        if (match != null) {
875	            owner.setPossibleDuplicate(true);
876	            owner.setPossibleDuplicateOf(match.getId());
877	        }
878	    }
879	
880	    /**
881	     * Caps the membership level of the owner being created so it cannot exceed one above the current
882	     * maximum membership level among its existing household members. A household member is a live (not
883	     * soft-deleted) owner carrying the same computed {@code householdId}. The owner's own derived level
884	     * ({@link Owner#getDerivedMembershipLevel()}) is returned capped at that maximum plus one; when the
885	     * owner belongs to no household, or no existing household member is found, no cap applies and the
886	     * derived level is returned unchanged. The owner being created has not been saved yet, so it is
887	     * never considered its own household member.
888	     *
889	     * @param owner the owner being created, with its household id and level-affecting fields set
890	     * @return the membership level to store, capped to the household ceiling where one exists
891	     */
892	    private Integer cappedMembershipLevel(Owner owner) {
893	        int derivedLevel = owner.getDerivedMembershipLevel();
894	        String householdId = owner.getHouseholdId();
895	        if (householdId == null || householdId.isBlank()) {
896	            return derivedLevel;
897	        }
898	        OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
899	            .filter(this::isNotDeleted)
900	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
901	            .mapToInt(Owner::getMembershipLevel)
902	            .max();
903	        if (maxHouseholdLevel.isEmpty()) {
904	            return derivedLevel;
905	        }
906	        return Math.min(derivedLevel, maxHouseholdLevel.getAsInt() + 1);
907	    }
908	
909	    /**
910	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
911	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
912	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
913	     * shares both automatically shares the same household id, so the household is keyed on
914	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
915	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
916	     * still land in the same household.
917	     *
918	     * @param lastName the owner's last name
919	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
920	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
921	     *         to no postcode-keyed household
922	     */
923	    private String computeHouseholdId(String lastName, String postcode) {
924	        if (postcode == null) {
925	            return null;
926	        }
927	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
928	    }
929	
930	    /**
931	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
932	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
933	     * the result is lower-cased.
934	     *
935	     * @param value the value to normalize, possibly {@code null}
936	     * @return the normalized value, or an empty string if {@code value} is {@code null}
937	     */
938	    private String normalizeForComparison(String value) {
939	        if (value == null) {
940	            return "";
941	        }
942	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
943	    }
944	
945	    /**
946	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
947	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
948	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
949	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
950	     * This normalized value is what gets stored and returned.
951	     *
952	     * @param address the raw address value submitted by the client, possibly {@code null}
953	     * @return the normalized address, or an empty string if {@code address} is {@code null}
954	     */
955	    private String normalizeAddress(String address) {
956	        if (address == null) {
957	            return "";
958	        }
959	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
960	        if (collapsed.isEmpty()) {
961	            return collapsed;
962	        }
963	        String[] tokens = collapsed.split(" ");
964	        StringBuilder normalized = new StringBuilder(collapsed.length());
965	        for (int i = 0; i < tokens.length; i++) {
966	            if (i > 0) {
967	                normalized.append(' ');
968	            }
969	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
970	        }
971	        return normalized.toString();
972	    }
973	
974	    /**
975	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
976	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
977	     * preferred when present, but either satisfies the address requirement, keeping the create
978	     * contract backward-compatible with earlier flat-address-only owners.
979	     *
980	     * @param ownerFieldsDto the submitted owner fields
981	     * @return {@code true} if an address is supplied in either form
982	     */
983	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
984	        return !isBlank(ownerFieldsDto.getAddressLine1())
985	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
986	    }
987	
988	    /**
989	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
990	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
991	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
992	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
993	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
994	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
995	     * working while letting everything that reads the address use the composed, normalized value.
996	     *
997	     * @param owner          the owner being created
998	     * @param ownerFieldsDto the submitted owner fields
999	     */
1000	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
1001	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
1002	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
1003	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
1004	                ? null
1005	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
1006	            owner.setAddressLine1(line1);
1007	            owner.setAddressLine2(line2);
1008	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
1009	        } else {
1010	            owner.setAddressLine1(null);
1011	            owner.setAddressLine2(null);
1012	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
1013	        }
1014	    }
1015	}
