241	     * the create endpoint's duplicate and identity checks ignore owners flagged deleted. Treated as
242	     * {@code false} when {@code null} (owners persisted before the column existed).
243	     */
244	    public Boolean getDeleted() {
245	        return this.deleted != null && this.deleted;
246	    }
247	
248	    public void setDeleted(Boolean deleted) {
249	        this.deleted = deleted;
250	    }
251	
252	    /**
253	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
254	     */
255	    @Transient
256	    public String getDisplayName() {
257	        return this.getLastName() + ", " + this.getFirstName();
258	    }
259	
260	    /**
261	     * The owner's salutation: the honorific {@link #getTitle() title} and the last name separated by
262	     * a single space (e.g. {@code 'DR who'}), or just the last name when the owner has no title.
263	     * Derived from the owner's own fields.
264	     */
265	    @Transient
266	    public String getSalutation() {
267	        if (this.title == null || this.title.isBlank()) {
268	            return this.getLastName();
269	        }
270	        return this.title + " " + this.getLastName();
271	    }
272	
273	    /**
274	     * The owner's initials: the upper-cased first letters of the first and last name,
275	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
276	     */
277	    @Transient
278	    public String getInitials() {
279	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
280	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
281	    }
282	
283	    /**
284	     * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by the
285	     * calendar year in which it ends: a date in July through December belongs to the fiscal year
286	     * ending the following calendar year, a date in January through June to the fiscal year ending
287	     * that same calendar year.
288	     */
289	    private static int fiscalYearOf(LocalDate date) {
290	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
291	    }
292	
293	    /**
294	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
295	     * the fiscal year (which starts on 1 July) that the business-day-adjusted {@code registrationDate}
296	     * falls in (e.g. {@code 'FY26'} for a registration date between 1 July 2025 and 30 June 2026).
297	     * Derived from the owner's own {@code registrationDate}; {@code null} until it is set.
298	     */
299	    @Transient
300	    public String getFiscalYear() {
301	        if (this.registrationDate == null) {
302	            return null;
303	        }
304	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
305	    }
306	
307	    /**
308	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
309	     * the last two digits of the fiscal year carried by the business-day-adjusted registration date
310	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own fields; {@code null} until both
311	     * the customer code and registration date are set.
312	     */
313	    @Transient
314	    public String getMembershipNumber() {
315	        if (this.customerCode == null || this.registrationDate == null) {
316	            return null;
317	        }
318	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
319	    }
320	
321	    /**
322	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
323	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
324	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
325	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
326	     */
327	    @Transient
328	    public Integer getCheckDigit() {
329	        if (this.customerCode == null) {
330	            return null;
331	        }
332	        int sum = 0;
333	        boolean dbl = true;
334	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
335	            char c = this.customerCode.charAt(i);
336	            if (c < '0' || c > '9') {
337	                continue;
338	            }
339	            int d = c - '0';
340	            if (dbl) {
341	                d *= 2;
342	                if (d > 9) {
343	                    d -= 9;
344	                }
345	            }
346	            sum += d;
347	            dbl = !dbl;
348	        }
349	        return (10 - (sum % 10)) % 10;
350	    }
351	
352	    /**
353	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
354	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
355	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
356	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
357	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
358	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
359	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
360	     */
361	    @Transient
362	    public Integer getMembershipPoints() {
363	        int points = 0;
364	        boolean hasEmail = this.email != null && !this.email.isBlank();
365	        if (hasEmail) {
366	            points += 2;
367	        }
368	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
369	        if (unique) {
370	            points += 1;
371	        }
372	        int householdSize = 1 + getPetsInternal().size();
373	        if (householdSize >= 3) {
374	            points += 2;
375	        }
376	        boolean tenured = this.registrationDate != null
377	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) > 0;
378	        if (tenured) {
379	            points += 3;
380	        }
381	        return points;
382	    }
383	
384	    /**
385	     * The owner's numeric membership level, from 1 to 4. By default it is derived from
386	     * {@link #getMembershipPoints()}: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
387	     * 4 for 6 or more points. When a level has been assigned and stored at creation time (the capped
388	     * level computed against the owner's household), that stored value is returned instead, so the
389	     * level read back for the owner reflects the household ceiling applied when the owner was created.
390	     */
391	    @Transient
392	    public Integer getMembershipLevel() {
393	        if (this.membershipLevel != null) {
394	            return this.membershipLevel;
395	        }
396	        return getDerivedMembershipLevel();
397	    }
398	
399	    /**
400	     * Stores the owner's membership level, overriding the value otherwise derived from the owner's
401	     * membership points. Used at creation time to persist the household-capped level.
402	     */
403	    public void setMembershipLevel(Integer membershipLevel) {
404	        this.membershipLevel = membershipLevel;
405	    }
406	
407	    /**
408	     * The owner's membership level derived purely from {@link #getMembershipPoints()}, before any
409	     * household cap: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more
410	     * points.
411	     */
412	    @Transient
413	    public Integer getDerivedMembershipLevel() {
414	        int points = getMembershipPoints();
415	        if (points >= 6) {
416	            return 4;
417	        }
418	        if (points >= 4) {
419	            return 3;
420	        }
421	        if (points >= 2) {
422	            return 2;
423	        }
424	        return 1;
425	    }
426	
427	    /**
428	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
429	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
430	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
431	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
432	     */
433	    @Transient
434	    public String getLocality() {
435	        if (this.customerCode == null) {
436	            return "UNKNOWN";
437	        }
438	        int dash = this.customerCode.indexOf('-');
439	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
440	    }
441	
442	    /**
443	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
444	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
445	     * {@code QLD -> 'Australia/Brisbane'}.
446	     */
447	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
448	        "NSW", "Australia/Sydney",
449	        "VIC", "Australia/Melbourne",
450	        "QLD", "Australia/Brisbane");
451	
452	    /**
453	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
454	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
455	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
456	     * the locality is not one of these regions.
457	     */
458	    @Transient
459	    public String getTimezone() {
460	        return REGION_TIMEZONE.get(getLocality());
461	    }
462	
463	    /**
464	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
465	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
466	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
467	     * owner has none), and the household id the stored shared identifier (empty when the owner is
468	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
469	     * are equal; because the telephone is part of the key, two members of the same household with
470	     * different telephones have different identity keys.
471	     */
472	    @Transient
473	    public String getIdentityKey() {
474	        String telephonePart = this.telephone == null ? "" : this.telephone;
475	        String emailPart = this.email == null ? "" : this.email;
476	        String householdPart = this.householdId == null ? "" : this.householdId;
477	        return telephonePart + "|" + emailPart + "|" + householdPart;
478	    }
479	
480	    /**
481	     * The owner's preferred contact channel, derived from the owner's own fields:
482	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
483	     */
484	    @Transient
485	    public String getContactPreference() {
486	        boolean hasEmail = this.email != null && !this.email.isBlank();
487	        return hasEmail ? "EMAIL" : "PHONE";
488	    }
489	
490	    /**
491	     * The owner's age band, derived from the owner's own fields: the whole number of years from
492	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
493	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
494	     * as of the registration date rather than today, so the band is stable over time. {@code null}
495	     * when the owner has no birth date (or no registration date to measure against).
496	     */
497	    @Transient
498	    public String getAgeBand() {
499	        if (this.birthDate == null || this.registrationDate == null) {
500	            return null;
501	        }
502	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
503	        if (age < 18) {
504	            return "MINOR";
505	        }
506	        if (age < 65) {
507	            return "ADULT";
508	        }
509	        return "SENIOR";
510	    }
511	
512	    protected Set<Pet> getPetsInternal() {
513	        if (this.pets == null) {
514	            this.pets = new HashSet<>();
515	        }
516	        return this.pets;
517	    }
518	
519	    protected void setPetsInternal(Set<Pet> pets) {
520	        this.pets = pets;
521	    }
522	
523	    public List<Pet> getPets() {
524	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
525	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
526	        return Collections.unmodifiableList(sortedPets);
527	    }
528	
529	    public void setPets(List<Pet> pets) {
530	        this.pets = new HashSet<>(pets);
531	    }
532	
533	    public void addPet(Pet pet) {
534	        getPetsInternal().add(pet);
535	        pet.setOwner(this);
536	    }
537	
538	    /**
539	     * Return the Pet with the given name, or null if none found for this Owner.
540	     *
541	     * @param name to test
542	     * @return true if pet name is already in use
543	     */
544	    public Pet getPet(String name) {
545	        return getPet(name, false);
546	    }
547	
548	    /**
549	     * Return the Pet with the given name, or null if none found for this Owner.
550	     *
551	     * @param name to test
552	     * @return true if pet name is already in use
553	     */
554	    public Pet getPet(String name, boolean ignoreNew) {
555	        name = name.toLowerCase();
556	        for (Pet pet : getPetsInternal()) {
557	            if (!ignoreNew || !pet.isNew()) {
558	                String compName = pet.getName();
559	                compName = compName.toLowerCase();
560	                if (compName.equals(name)) {
561	                    return pet;
562	                }
563	            }
564	        }
565	        return null;
566	    }
567	
568	    public Pet getPet(Integer petId) {
569	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
570	    }
571	
572	    @Override
573	    public String toString() {
574	        return new ToStringCreator(this)
575	
576	            .append("id", this.getId())
577	            .append("new", this.isNew())
578	            .append("lastName", this.getLastName())
579	            .append("firstName", this.getFirstName())
580	            .append("address", this.address)
581	            .append("city", this.city)
582	            .append("telephone", this.telephone)
583	            .toString();
584	    }
585	}
